/**
 * Сценарии для шлюза «не по делу — молчать» (ai/relevance.ts).
 * Тексты выдуманные, но по образцу настоящих (русский, таджикский кириллицей без
 * спецбукв, смесь). expect:
 *   answer  — бот должен ответить по существу (по делу или приветствие)
 *   silent  — молчать совсем
 *   clarify — не ясно: один нейтральный вопрос (или к человеку), не гадать
 */
export type Expect = "answer" | "silent" | "clarify";
export interface Scenario {
  id: string;
  text: string;
  expect: Expect;
  group: string;
}

const s = (group: string, expect: Expect, texts: string[]): Scenario[] =>
  texts.map((text, i) => ({ id: `${group}-${i + 1}`, text, expect, group }));

